import{_ as i,a0 as a,w as l,s as u,ao as n,I as s,x as e,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"技術勝過教條——關於開源的一些見解 | LCTT x X-CMD","titleTemplate":false,"description":"技術勝過教條——關於開源的一些見解 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"技術勝過教條——關於開源的一些見解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"技術勝過教條——關於開源的一些見解 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Technology Trumps Dogma, And Other Open Source Insights","title":"技術勝過教條——關於開源的一些見解","tag":"201309","desc":""},"relativePath":"201309/Technology Trumps Dogma, And Other Open Source Insights.md","filePath":"[post].md"}'),m={name:"201309/Technology Trumps Dogma, And Other Open Source Insights.md"};function d(g,t,T,f,S,_){const o=a("Link");return l(),u("div",null,[t[17]||(t[17]=n('<h1 id="技術勝過教條——關於開源的一些見解" tabindex="-1">技術勝過教條——關於開源的一些見解 <a class="header-anchor" href="#技術勝過教條——關於開源的一些見解" aria-label="Permalink to “技術勝過教條——關於開源的一些見解”">​</a></h1><h2 id="為何marten-mickos-是開源領域中最受尊敬的領導者之一-本文將告訴你原因。" tabindex="-1">為何Marten Mickos 是開源領域中最受尊敬的領導者之一，本文將告訴你原因。 <a class="header-anchor" href="#為何marten-mickos-是開源領域中最受尊敬的領導者之一-本文將告訴你原因。" aria-label="Permalink to “為何Marten Mickos 是開源領域中最受尊敬的領導者之一，本文將告訴你原因。”">​</a></h2><p><img src="http://readwrite.com/files/styles/630_0su/public/files/files/cloud/marten-mickos.jpg" alt="Technology Trumps Dogma, And Other Open Source Insights"></p>',3)),s("p",null,[t[1]||(t[1]=e("幾周前，我拜訪了Eucalyptus System的CEO Marten Mickos，想請他",-1)),p(o,{href:"http://readwrite.com/2013/08/27/linux-turns-22-but-open-source-is-eternal#awesm=~oh8KYvjJatv2EW"},{default:r(()=>[...t[0]||(t[0]=[e("就開源領域中的人員構成變化問題發表一些看法",-1)])]),_:1}),t[2]||(t[2]=e("。他也確實給出了他的看法，而且是用明顯的Mickos風格。",-1))]),t[18]||(t[18]=n("<p>我本打算分享Mickos所有天才般的見解，但不幸的是，由於篇幅限制，很多精彩言論只能被迫砍掉。Mickos曾經幫助MySQL成為世界上最受歡迎的資料庫，如今，他正嘗試讓一個開源雲計算產品達到同樣的高度。</p><p>經歷過多次成功與失敗後，Mickos有無數有關開源的智慧分享給我們。例如當開源開發者一直在努力迴避企業對某一個開源項目的影響時，Mickos卻提醒我們，金錢是至關重要的發展資金，更何況營銷和文檔。那種愛好和平、拒絕金錢的開源項目只能是一個神話。</p><p><strong>金錢對於開源的重要性...</strong></p><p>沒有錢，開源就是死路一條。</p><p><strong>開源商業化戰略背後的基本原則...</strong></p><p>有些人為了省錢浪費大把時間，有人卻花錢來節約時間。</p><p><strong>開源開發者的人員構成變化...</strong></p><p>過去，開源社區的開發者們看起來都像是真正的牛仔——時刻表現出真正的自己，遵循自己的個性道路，追尋他們幾乎無限的自由。今天，許多開源社區的開發者們卻很樂意受僱於與開源精神相悖的大公司（例如Google，HP，IBM，Oracle等等）。當他們發表公眾言論的時候，還會標明其言論僅代表自己的個人觀點，並非所在公司的官方聲明。和過去相比，如今自願的服從已經很普遍。</p><p><strong>非盈利版權授權及管理的作用...</strong></p><p>FOSS（Free Open Source Software自由及開源軟件）許可證及其管理模式的目的並不是為了讓志趣相投的人們協作在一起，儘管它也有這個效果。FOSS是為了讓意見不一致的人們在一起協作。開源的美麗就在於能夠讓不同的人們為相同的產品貢獻代碼。</p><p><strong>領袖...</strong></p><p>無論在精英制度中還是在大眾生產模式中，人們都需要領袖。</p><p><strong>批評性意見...</strong></p><p>在可持續發展的基礎上，如果你能真正熱愛嚴厲的批評，如果你能對別人的貢獻無論大小與類型，都真正表現出無比的熱情與感激，你一定能在開源領域獲得無比的成功。</p><p>當人們抱怨你的開源項目時，你只需要記住：忠言逆耳。他們其實是愛你的。</p>",15)),s("p",null,[t[4]||(t[4]=e("如果沒有人反對你的開源產品或項目，其實你並不是真的受歡迎。",-1)),p(o,{href:"http://readwrite.com/2013/02/25/haters-as-a-leading-indicator-of-success#awesm=~oh8MUh09kvHxy3"},{default:r(()=>[...t[3]||(t[3]=[e("反對者恰恰是你通向成功的路標",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[19]||(t[19]=n("<p><strong>品牌的作用...</strong></p><p>授權問題同時更多的是一個品牌問題。紅帽將他們的開源社區冠以“Red Hat”品牌並商業化後，還建立了非商業化品牌Fedora。MySQL和JBoss卻恰好相反，他們從社區到商用都使用同一個品牌。當你fork的時候，因為該品牌並未包含在開源授權許可中，所以你必須使用不同的名字。</p><p><strong>開源&quot;神學&quot;中顯著的不一致性...</strong></p><p>開源的人可能是教條主義的，特別是對別人。出於正統或純潔性，他們會急切的要求一些項目按照這樣或那樣的方式進行。但是同時他們卻愉快地使用諸如iBooks這樣的封閉系統，因為他們崇拜這些產品。技術勝過教條。冷靜是關鍵。關於所有這些我所説的並不是抱怨，而是一種觀察。要在開源中成功，你必須學會接受它並善加利用。</p><p><strong>開源過去十年來的變化...</strong></p><p>過去，人們不知道它是什麼，如何工作，為何這麼做，怎樣創造出偉大的軟件，為何它沒有自生自滅等等。這也是為什麼LAMP能夠將它推向財富雜誌的封面——它是如此新穎和迷人。今天，人們知道開源，還知道開源是軟件世界不可或缺的一部分。過去，當權者反對它；今天，當權者擁抱它(至少假裝如此)。</p><p>過去，做開源的人只有非常少的一部分人，他們關注開源本身，在Blog中討論開源的意義，思考開源的商業模式。今天，做開源的人包括程序員、社區領袖、測試人員、使用者、投資者還有作家。</p><p>過去，無論從哪方面看，授權都是很大的一個問題。今天，它只是一個話題而已。</p><p>過去，開源只涉及到少部分項目中的少部分人。今天，這類項目的數字大概增加了100-1000倍。</p><p>過去，開源的相關基礎設施並不存在。今天，我們有Wiki，Github，Jira等服務，方便地告訴我們如何運行和管理一個開源項目。</p><p>十年前，人們願意下載發行版。今天,人們上傳鏡像(到雲端)。</p><p><strong>開源過去十年來未曾改變的...</strong></p><p>仍然有大量肆無忌憚的狂熱者，他們常常已經接近“很傻很天真”的邊緣，他們為開源帶來令人震驚的收穫，但同時也不可避免地帶來一些缺點。</p><p>開源仍然吸引着優秀的天才。</p><p>最成功的開源項目往往以開發者為目標。而那些供普通消費者或非技術人員使用的產品往往並不成功。但往往也有一些著名的例外，例如Firefox,Android,也許OpenOffice也算一個。</p>",15)),s("p",null,[t[7]||(t[7]=e("via:",-1)),p(o,{href:"http://readwrite.com/2013/09/13/marten-mickos-interview-open-source-mysql-eucalyptus"},{default:r(()=>[...t[6]||(t[6]=[e("http://readwrite.com/2013/09/13/marten-mickos-interview-open-source-mysql-eucalyptus",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/portal.php"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))]),s("p",null,[t[15]||(t[15]=e("譯者：",-1)),p(o,{href:"http://linux.cn/space/14801"},{default:r(()=>[...t[13]||(t[13]=[e("Mr小眼兒",-1)])]),_:1}),t[16]||(t[16]=e(" 校對：",-1)),p(o,{href:"http://linux.cn/space/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})])])}const x=i(m,[["render",d]]);export{M as __pageData,x as default};
